// Fictional Trading 212 statements (v0.34.0), laid out like the two documents the owner brought in (an "Activity statement"
// and a "Transactions Statement"): every name, number and amount here is made up. Its two transfers in match two of
// the first direct fixture's payments to a broker (tests/fixtures/statements.ts), a day apart or on the same day.
import type { Placed } from './pdf'

/** The ISA's cash movements, newest first, as both documents print them. */
const ROWS = [
  { iso: '2026-10-09 13:47:01', dmy: '09/10/2026 13:47:01', type: 'JP Morgan payout', pence: -7525, note: 'Sent to Bank Account 00-00-00 / 12345678' },
  { iso: '2026-10-05 01:08:01', dmy: '05/10/2026 01:08:01', type: 'Interest on cash', pence: 2, note: 'Interest on cash' },
  { iso: '2026-10-02 09:00:00', dmy: '02/10/2026 09:00:00', type: 'TrueLayer', pence: 5000, note: 'Transaction ID: 00000000-aaaa-bbbb-cccc-000000000002' },
  { iso: '2026-10-01 01:08:21', dmy: '01/10/2026 01:08:21', type: 'Interest on cash', pence: 4, note: 'Interest on cash' },
  { iso: '2026-09-30 10:15:00', dmy: '30/09/2026 10:15:00', type: 'TrueLayer', pence: 10000, note: 'Transaction ID: 00000000-aaaa-bbbb-cccc-000000000001' },
  { iso: '2026-09-29 01:06:00', dmy: '29/09/2026 01:06:00', type: 'Interest on cash', pence: 3, note: 'Interest on cash' },
] as const

/** What a person reads in either: the account, its days, and its transfers (not its interest), oldest first. */
export const TRADING212_EXPECT = [
  {
    account: 'Trading 212 ···0001',
    from: '2026-09-20',
    to: '2026-10-18',
    lines: [
      ['2026-09-30', 'TrueLayer', 10000, '', null],
      ['2026-10-02', 'TrueLayer', 5000, '', null],
      ['2026-10-09', 'JP Morgan payout', -7525, '', null],
    ],
  },
]

const amount = (pence: number, sign = true) => `${pence < 0 && sign ? '-' : ''}£${(Math.abs(pence) / 100).toFixed(2).replace(/\.00$/, '')}`
const plain = (pence: number) => String(pence / 100)

// ---------- The Transactions Statement: a cover, then each account's table (AMOUNT CURRENCY TIME TYPE NOTES) ----------

const txHeading = (y: number): Placed[] => [
  { text: 'AMOUNT', x: 24, y, size: 7 },
  { text: 'CURRENCY', x: 128, y, size: 7 },
  { text: 'TIME', x: 266, y, size: 7 },
  { text: 'TRANSACTION TYPE', x: 330, y, size: 7 },
  { text: 'NOTES', x: 500, y, size: 7 },
]

const txRows = (rows: readonly (typeof ROWS)[number][], top: number): Placed[] =>
  rows.flatMap((row, i) => {
    const y = top - i * 24
    return [
      { text: plain(row.pence), x: 24, y, size: 8 },
      { text: 'GBP', x: 128, y, size: 8 },
      { text: row.dmy, x: 206, y, size: 8 },
      { text: row.type, x: 330, y, size: 8 },
      { text: row.note, x: 400, y, size: 8 },
    ]
  })

const txFoot: Placed = { text: 'Trading 212 is a trading name of Trading 212 UK Ltd. Trading 212 UK Ltd. is registered in England and Wales.', x: 24, y: 30, size: 6 }

export const TRANSACTIONS_LIKE: Placed[][] = [
  [
    { text: 'Transactions Statement', x: 200, y: 600, size: 20 },
    { text: 'Generated by Trading 212 UK Ltd. on 19 October 2026 at 14:31 (UTC).', x: 150, y: 570, size: 9 },
    { text: 'Account holder', x: 150, y: 520, size: 9 },
    { text: 'A N Other', x: 300, y: 520, size: 9 },
    { text: 'Customer ID', x: 150, y: 480, size: 9 },
    { text: '10000001', x: 300, y: 480, size: 9 },
    { text: 'Document period', x: 150, y: 460, size: 9 },
    { text: '20.09.2026 - 18.10.2026', x: 300, y: 460, size: 9 },
    txFoot,
  ],
  [{ text: 'Invest Account', x: 250, y: 560, size: 16 }, { text: 'Account value: £0.00', x: 24, y: 520, size: 9 }, { text: 'Account ID: 20000002', x: 24, y: 504, size: 9 }, ...txHeading(474), { text: 'No data available', x: 250, y: 440, size: 8 }, txFoot],
  [
    { text: 'ISA Account', x: 250, y: 560, size: 16 },
    { text: 'Account value: £5,000.00', x: 24, y: 520, size: 9 },
    { text: 'Account ID: 20000001', x: 24, y: 504, size: 9 },
    ...txHeading(474),
    ...txRows(ROWS.slice(0, 3), 453),
    txFoot,
  ],
  // The table carries on, headed again and with no title.
  [...txHeading(540), ...txRows(ROWS.slice(3), 515), txFoot],
  [{ text: 'Cash ISA Account', x: 250, y: 560, size: 16 }, { text: 'Account value: £0.00', x: 24, y: 520, size: 9 }, { text: 'Account ID: 20000003', x: 24, y: 504, size: 9 }, ...txHeading(474), { text: 'No data available', x: 250, y: 440, size: 8 }, txFoot],
]

// ---------- The Activity statement: an overview of every account, then each one's trades, positions, cash and transactions ----------

const BLOCKS = [
  { x: 20, name: 'Trading 212 Invest', id: '20000002', rows: [['Deposits', 0], ['Withdrawals', 0], ['Account value', 0]] },
  { x: 160, name: 'Trading 212 Stocks ISA', id: '20000001', rows: [['Deposits', 15000], ['Withdrawals', -7525], ['Dividends and distributions', 188], ['Interest on cash', 9], ['Account value', 500000]] },
  { x: 300, name: 'Trading 212 Cash ISA', id: '20000003', rows: [['Deposits', 0], ['Withdrawals', 0], ['Account balance', 0]] },
  { x: 440, name: 'Trading 212 CFD', id: '20000004', rows: [['Deposits', 0], ['Withdrawals', 0], ['Account value', 0]] },
] as const

/** The overview prints every sum with its pence: "£1,234.56", "-£75.25". */
const printed = (pence: number) => `${pence < 0 ? '-' : ''}£${(Math.abs(pence) / 100).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

const overview = (over: { deposits?: number } = {}): Placed[] =>
  BLOCKS.flatMap((b) => [
    { text: b.name, x: b.x, y: 440, size: 9 },
    { text: `Account ID: ${b.id}`, x: b.x, y: 426, size: 7 },
    ...b.rows.flatMap(([label, pence], i): Placed[] => [
      { text: label as string, x: b.x + 4, y: 400 - i * 16, size: 7 },
      { text: printed(over.deposits !== undefined && label === 'Deposits' && b.id === '20000001' ? over.deposits : (pence as number)), x: b.x + 130, y: 400 - i * 16, size: 7, right: true },
    ]),
  ])

const acHeading = (y: number): Placed[] => [
  { text: 'TIME', x: 18, y, size: 7 },
  { text: 'TYPE', x: 128, y, size: 7 },
  { text: 'AMOUNT', x: 480, y, size: 7, right: true },
]

const acRows = (rows: readonly (typeof ROWS)[number][], top: number): Placed[] =>
  rows.flatMap((row, i) => {
    const y = top - i * 22
    return [
      { text: row.iso, x: 18, y, size: 8 },
      { text: row.type, x: 128, y, size: 8 },
      { text: amount(row.pence), x: 480, y, size: 8, right: true },
    ]
  })

/** `deposits`: what the overview says the deposits came to, when a test wants it wrong. */
export const activityLike = (deposits?: number): Placed[][] => [
  [
    { text: 'Activity statement', x: 220, y: 560, size: 20 },
    { text: 'Generated by Trading 212 UK Ltd. on 19 October 2026, covering from 19.09.2026 21:00 (UTC) to 18.10.2026 21:59 (UTC).', x: 40, y: 530, size: 7 },
    { text: 'Overview', x: 250, y: 480, size: 14 },
    ...overview(deposits === undefined ? {} : { deposits }),
  ],
  // Trades carry times in the same form as transactions: they are no money moved.
  [
    { text: 'Stocks ISA account - executed trades', x: 150, y: 560, size: 14 },
    { text: 'EXECUTION TIME', x: 18, y: 520, size: 7 },
    { text: 'INSTRUMENT', x: 128, y: 520, size: 7 },
    { text: 'VALUE', x: 480, y: 520, size: 7, right: true },
    { text: '2026-10-01 07:05:49', x: 18, y: 500, size: 8 },
    { text: 'EXMP', x: 128, y: 500, size: 8 },
    { text: '£100.18', x: 480, y: 500, size: 8, right: true },
    { text: '2026-10-02 13:39:46', x: 18, y: 478, size: 8 },
    { text: 'EXMQ', x: 128, y: 478, size: 8 },
    { text: '£102.19', x: 480, y: 478, size: 8, right: true },
  ],
  [{ text: 'Stocks ISA account - transactions and dividends', x: 120, y: 560, size: 14 }, { text: 'Transactions', x: 18, y: 530, size: 11 }, ...acHeading(510), ...acRows(ROWS.slice(0, 3), 488)],
  // The table carries on with no title, and the dividends follow on the same page.
  [
    ...acHeading(540),
    ...acRows(ROWS.slice(3), 518),
    { text: 'Dividends', x: 18, y: 430, size: 11 },
    { text: 'INSTRUMENT', x: 18, y: 410, size: 7 },
    { text: 'PAY DATE', x: 200, y: 410, size: 7 },
    { text: 'TOTAL AMOUNT', x: 480, y: 410, size: 7, right: true },
    { text: 'EXMP', x: 18, y: 390, size: 8 },
    { text: '01.10.2026 14:39', x: 200, y: 390, size: 8 },
    { text: '£1.88', x: 480, y: 390, size: 8, right: true },
  ],
  [{ text: 'Cash ISA account - transactions', x: 150, y: 560, size: 14 }, ...acHeading(520), { text: 'No data available', x: 220, y: 490, size: 8 }],
]
